		// a functionality error than the reset being implemented asynchronously.

	endtask


	wire [3:0][2:0] val = { 3'h7, 3'h3, 3'h1, 3'h0 };
	integer sval;
	initial begin
		reset <= 1;
		s <= 1;
		reset_test();


		@(posedge clk) s <= 0;
